#ifdef ENABLE_MQTT_TLS
typedef struct _MqttTls {
    WOLFSSL_CTX         *ctx;
    WOLFSSL             *ssl;
    int                 sockRcRead;
    int                 sockRcWrite;
    int                 timeout_ms_read;
    int                 timeout_ms_write;
} MqttTls;
